export function getModuleItems(mod: PeakModule): PeakItemData[] {
  return PEAK_MODULES[mod].items;
}

export function getModuleCount(mod: PeakModule): number {
  return PEAK_MODULES[mod].items.length;
}

export function getModuleFactors(mod: PeakModule): Array<{ key: string; nameAr: string; nameEn: string }> {
  const seen = new Map<string, { nameAr: string; nameEn: string }>();
  for (const item of PEAK_MODULES[mod].items) {
    if (!seen.has(item.factor)) seen.set(item.factor, { nameAr: item.factorNameAr, nameEn: item.factorNameEn });
  }
  return Array.from(seen.entries()).map(([key, v]) => ({ key, ...v }));
}

